import React from "react";
import ChoiceBar from "./ChoiceBar";
 
export default function VotingComponent(question) {
return <div className="Row VotingRow Spacer">
    <div className="Head">
        <h1 className="Title">
            {question.frage}
            <div className="Badge">10 Votes</div>
        </h1>
        <div className="Description Emphasis">{ question.details }</div>
    </div>
    <ChoiceBar title={"WebTech"} percent={90}/>
    <ChoiceBar title={"DB"} percent={99}/>
</div>;
}
